import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"strace","description":"","frontmatter":{},"headers":[],"relativePath":"notes/linux-kernel/tracing-debugging/strace.md","filePath":"notes/linux-kernel/tracing-debugging/strace.md"}'),d={name:"notes/linux-kernel/tracing-debugging/strace.md"};function c(i,e,r,o,l,p){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="strace" tabindex="-1">strace <a class="header-anchor" href="#strace" aria-label="Permalink to &quot;strace&quot;">​</a></h1><p><code>strace</code> 是一个利用 Linux <code>ptrace</code> 实现的用户态工具，用于拦截并记录一个进程所调用的 <code>syscall</code> 和接收到的 <code>signals</code>。</p><h2 id="输出解释" tabindex="-1">输出解释 <a class="header-anchor" href="#输出解释" aria-label="Permalink to &quot;输出解释&quot;">​</a></h2><p>这里以运行 <code>strace ls</code> 的输出为例，解释 <code>strace</code> 输出的含义。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/*</span></span>
<span class="line"><span> * 每一行包括一个系统调用名，随后是括号中的参数和返回值</span></span>
<span class="line"><span> */</span></span>
<span class="line"><span>execve(&quot;/usr/bin/ls&quot;, [&quot;ls&quot;], 0x7ffe2d5b0e10 /* 26 vars */) = 0</span></span>
<span class="line"><span>brk(NULL)                               = 0x64eacb6ad000</span></span>
<span class="line"><span>mmap(NULL, 8192, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0) = 0x7b1c5ab8f000</span></span>
<span class="line"><span>/*</span></span>
<span class="line"><span> * 错误返回 error symbol 和 error string</span></span>
<span class="line"><span> */</span></span>
<span class="line"><span>access(&quot;/etc/ld.so.preload&quot;, R_OK)      = -1 ENOENT (No such file or directory)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>......</span></span>
<span class="line"><span></span></span>
<span class="line"><span>exit_group(0)                           = ?</span></span>
<span class="line"><span>+++ exited with 0 +++</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>当使用 <code>kill &lt;pid&gt;</code> 杀死一个 <code>strace sleep 666</code> 进程时，可以看到：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/*</span></span>
<span class="line"><span> * signal symbol 和 siginfo structure 的内容会被打印</span></span>
<span class="line"><span> */</span></span>
<span class="line"><span>clock_nanosleep(CLOCK_REALTIME, 0, {tv_sec=666, tv_nsec=0}, {tv_sec=655, tv_nsec=219876115}) = ? ERESTART_RESTARTBLOCK (Interrupted by signal)</span></span>
<span class="line"><span>--- SIGTERM {si_signo=SIGTERM, si_code=SI_USER, si_pid=13621, si_uid=1000} ---</span></span>
<span class="line"><span>+++ killed by SIGTERM +++</span></span>
<span class="line"><span>Terminated</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>当一个 <code>syscall</code> 正在调用时，另一个被追踪的进/线程被调用，<code>strace</code> 会 <em>try to preserve</em> 事件的时序：用 <code>unfinished</code> 标注尚未完成的 <code>syscall</code>，用 <code>resumed</code> 标注恢复并且执行完毕的 <code>syscall</code>。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[pid 28772] select(4, [3], NULL, NULL, NULL &lt;unfinished ...&gt;</span></span>
<span class="line"><span>[pid 28779] clock_gettime(CLOCK_REALTIME, {tv_sec=1130322148, tv_nsec=3977000}) = 0</span></span>
<span class="line"><span>[pid 28772] &lt;... select resumed&gt;)     = 1 (in [3])</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>当一个 <code>syscall</code> 被 signal 打断，<code>syscall</code> 可能 restart 或返回错误，这里以 restart 为例：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>read(0, 0x7ffff72cf5cf, 1)            = ? ERESTARTSYS (To be restarted)</span></span>
<span class="line"><span>--- SIGALRM {si_signo=SIGALRM, si_code=SI_KERNEL} ---</span></span>
<span class="line"><span>rt_sigreturn({mask=[]})               = 0</span></span>
<span class="line"><span>read(0, &quot;&quot;, 1)                        = 0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>strace</code> 会尝试解引用指针并 decode 结构体，使其更易阅读。对于未知的 <code>syscall</code>，<code>strace</code> 将<strong>以十六进制形式打印，并加上 <code>syscall_</code> 前缀</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>syscall_0xbad(0x1, 0x2, 0x3, 0x4, 0x5, 0x6) = -1 ENOSYS (Function not implemented)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol><li>结构体使用 <code>{}</code> 表示</li><li>普通数组使用 <code>[]</code>，元素之间逗号分隔</li><li>bit-sets 也用 <code>[]</code>，但元素之间用空格分隔</li><li><code>[]</code> 表示空集</li><li><code>~[]</code> 表示空集的补集</li></ol><h2 id="strace-attach" tabindex="-1">strace attach <a class="header-anchor" href="#strace-attach" aria-label="Permalink to &quot;strace attach&quot;">​</a></h2><p><code>ptrace attach</code> 一个 process，指的是：一个进程通过 <code>ptrace()</code> 系统调用，接管并跟踪另一个已经运行的进程或线程。</p><p>典型调用：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ptrace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(PTRACE_ATTACH, pid, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>执行成功后，大致会发生以下过程：</p><ol><li>内核建立 tracer 与目标线程之间的 ptrace 跟踪关系。</li><li><code>PTRACE_ATTACH</code> 会使目标线程收到 SIGSTOP 并进入暂停状态。</li><li>tracer 通过 <code>waitpid()</code> 等待并确认目标已经停止。</li><li>目标停止后，tracer 可以读取或修改其寄存器、访问进程地址空间、设置断点、单步执行、跟踪系统调用等。</li><li>tracer 使用 <code>PTRACE_CONT</code> 让目标继续运行，或者使用 <code>PTRACE_DETACH</code> 解除跟踪关系。</li></ol><h2 id="常用选项" tabindex="-1">常用选项 <a class="header-anchor" href="#常用选项" aria-label="Permalink to &quot;常用选项&quot;">​</a></h2><h3 id="_1-指定跟踪对象" tabindex="-1">1. 指定跟踪对象 <a class="header-anchor" href="#_1-指定跟踪对象" aria-label="Permalink to &quot;1. 指定跟踪对象&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>-p &lt;pid&gt;</code></td><td>attach 到已运行的进程。可重复指定以跟踪多个进程。</td><td><code>strace -p 1234</code></td></tr><tr><td><code>-f</code></td><td>跟踪 <code>fork</code>、<code>vfork</code>、<code>clone</code> 创建的子进程和线程。</td><td><code>strace -f ./server</code></td></tr><tr><td><code>-ff</code></td><td>跟踪子进程，并为每个进程分别写入输出文件。</td><td><code>strace -ff -o trace ./server</code></td></tr></tbody></table><p>附加到进程通常需要相应权限。跟踪多线程程序时应使用 <code>-f</code>，否则可能遗漏线程发起的系统调用。</p><h3 id="_2-筛选系统调用" tabindex="-1">2. 筛选系统调用 <a class="header-anchor" href="#_2-筛选系统调用" aria-label="Permalink to &quot;2. 筛选系统调用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>-e trace=&lt;set&gt;</code></td><td>只跟踪指定类别或名称的系统调用。</td><td><code>strace -e trace=file ls</code></td></tr><tr><td><code>-e trace=&lt;call&gt;</code></td><td>只跟踪一个或多个具体调用。</td><td><code>strace -e trace=openat,read ls</code></td></tr><tr><td><code>-e signal=&lt;set&gt;</code></td><td>只显示指定信号相关事件。</td><td><code>strace -e signal=SIGTERM -p 1234</code></td></tr><tr><td><code>-e trace=%network</code></td><td>跟踪网络相关系统调用。</td><td><code>strace -e trace=%network ./client</code></td></tr><tr><td><code>-e trace=%process</code></td><td>跟踪进程创建、执行和退出。</td><td><code>strace -e trace=%process ./script</code></td></tr></tbody></table><p>常见类别包括 <code>%file</code>、<code>%network</code>、<code>%process</code>、<code>%memory</code> 和 <code>%signal</code>。可以用 <code>-e trace=!openat</code> 排除某个调用，减少无关输出。</p><h3 id="_3-控制输出内容" tabindex="-1">3. 控制输出内容 <a class="header-anchor" href="#_3-控制输出内容" aria-label="Permalink to &quot;3. 控制输出内容&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>-o &lt;file&gt;</code></td><td>将输出写入文件，不与被跟踪程序的标准输出混在一起。</td><td><code>strace -o trace.log ./app</code></td></tr><tr><td><code>-s &lt;n&gt;</code></td><td>设置字符串最大打印长度，默认值较短。</td><td><code>strace -s 256 ./app</code></td></tr><tr><td><code>-y</code></td><td>将文件描述符解码为对应的文件或 socket 路径。</td><td><code>strace -y -e trace=read,write ./app</code></td></tr><tr><td><code>-yy</code></td><td>在 <code>-y</code> 基础上尽可能显示 socket 的详细信息。</td><td><code>strace -yy -e trace=network ./app</code></td></tr><tr><td><code>-v</code></td><td>更详细地打印结构体字段。可重复使用以增加详细程度。</td><td><code>strace -v ./app</code></td></tr></tbody></table><p>需要查看完整参数时，可结合使用 <code>-s</code> 和 <code>-yy</code>。跟踪输出可能包含敏感数据，应妥善保护日志文件。</p><h3 id="_4-记录时间与耗时" tabindex="-1">4. 记录时间与耗时 <a class="header-anchor" href="#_4-记录时间与耗时" aria-label="Permalink to &quot;4. 记录时间与耗时&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>-t</code> / <code>-tt</code> / <code>-ttt</code></td><td>分别以秒、微秒或 Unix 时间戳显示时间。</td><td><code>strace -tt ./app</code></td></tr><tr><td><code>-T</code></td><td>在每个系统调用末尾显示耗时。</td><td><code>strace -T ./app</code></td></tr><tr><td><code>-r</code></td><td>显示相邻输出行之间的相对时间间隔。</td><td><code>strace -r ./app</code></td></tr><tr><td><code>-w</code></td><td>显示系统调用等待时间；通常与 <code>-c</code> 结合使用。</td><td><code>strace -cw ./app</code></td></tr></tbody></table><p>定位耗时较长的系统调用：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">strace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ttT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trace=file</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file.trace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./app</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_5-统计与调用栈" tabindex="-1">5. 统计与调用栈 <a class="header-anchor" href="#_5-统计与调用栈" aria-label="Permalink to &quot;5. 统计与调用栈&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>-c</code></td><td>汇总系统调用次数、错误数和耗时，不打印逐条调用。</td><td><code>strace -c ./app</code></td></tr><tr><td><code>-C</code></td><td>在打印逐条调用的同时显示统计结果。</td><td><code>strace -C ./app</code></td></tr><tr><td><code>-k</code></td><td>尝试为每个系统调用打印用户态调用栈。</td><td><code>strace -k ./app</code></td></tr></tbody></table><p><code>-c</code> 用于查看系统调用的总体开销；如果还需要保留调用顺序，应使用 <code>-C</code> 或另行记录明细。</p><h3 id="按场景选择" tabindex="-1">按场景选择 <a class="header-anchor" href="#按场景选择" aria-label="Permalink to &quot;按场景选择&quot;">​</a></h3><ul><li><strong>文件访问异常</strong>：<code>strace -f -e trace=%file -s 256 ./app</code></li><li><strong>网络连接异常</strong>：<code>strace -f -yy -e trace=%network ./app</code></li><li><strong>定位慢系统调用</strong>：<code>strace -f -ttT -o trace.log ./app</code></li><li><strong>查看调用开销</strong>：<code>strace -f -c ./app</code></li><li><strong>分析已运行进程</strong>：<code>strace -f -p &lt;pid&gt;</code></li></ul><p>选项可以组合使用。排障时可先用 <code>-e trace=&lt;set&gt;</code> 缩小范围，再根据需要增加 <code>-T</code>、<code>-s</code>、<code>-y</code> 或 <code>-o</code>。</p>`,40)])])}const u=a(d,[["render",c]]);export{b as __pageData,u as default};
